 "content": "def transform(grid):
    """Continue a long horizontal foreground line across an empty suffix."""
    out=[row[:] for row in grid]
    bg=grid[0][0]
    for r,row in enumerate(grid):
        # A completed line is the last run of non-background cells in its row.
        # It is extended only when length is at least 4 and has a blank tail.
        if not row or row[-1] != bg:
            continue
        j=len(row)-1
        while j>=0 and row[j]==bg:
            j-=1
        if j<0:
            continue
        color=row[j]
        start=j
        while start>0 and row[start-1]==color:
            start-=1
        if j-start+1>=4:
            for c in range(j+1,len(row)):
                out[r][c]=1
    return out
